# ABOUTME: Grammar and rule definitions for Chalk parser
# ABOUTME: Provides GrammarRule and Grammar classes for defining parsing grammars
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;

class Chalk::GrammarRule {

    # Supports both exact token matching and lexeme/regex patterns for terminals
    # Use parse() for pre-tokenized input, parse_string() for lexeme matching
    #
    # TODO: Consider matrix-based Earley parsing optimization
    # See: https://medium.com/@celine.y.lee/fast-earley-parsing-2216fb0909a3
    # Matrix operations could optimize prediction/completion phases while
    # lexemes handle terminal matching independently
    use overload '""' => 'to_string';

    state $next_id = 0;    # auto-incrementing rule ID
    field $id  :reader = $next_id++;
    field $lhs :param :reader;
    field $rhs :param :reader;
    field $probability :param :reader = 1.0;
    field $nullable;

    method is_right_recursive() { $lhs eq $rhs->[-1] }
    method is_left_recursive()  { $lhs eq $rhs->[0] }

    method is_nullable( $grammar, $seen = {} ) {
        return $nullable if defined($nullable);    # memoize nullable

        # Empty production is nullable
        return $nullable = 1 if @$rhs == 0;

        # All symbols in RHS must be nullable
        return $nullable = 1 if all {
            my @rules = $grammar->rules_for($_);

            # Terminals (no rules) - check if nullable
            unless (@rules) {
                # For regex terminals, test if they match empty string
                if (ref($_) eq 'Regexp') {
                    return "" =~ $_;
                }
                # String terminals are not nullable (empty string would be in grammar as [])
                return 0;
            }

            # In cycle, assume not nullable
            return 0 if $seen->{$_};

            # Check if this symbol is nullable via any of its rules
            $seen->{$_} = 1;
            return 0 unless any { $_->is_nullable( $grammar, $seen ) } @rules;
        } @$rhs;

        return $nullable = 0;
    }

    method to_string(@) {
        return "($id) $lhs -> " . join( ' ', $rhs->@* );
    }

    method terminal_to_regex($terminal) {
        state %seen;

        # Convert terminal to regex pattern
        # If already a regex, return as-is
        # If string literal, escape and convert to regex
        return $seen{$terminal} //=
          ref($terminal) eq 'Regexp' ? $terminal : qr/\Q$terminal\E/;
    }

    # Default semantic action: return children as array (for AST construction)
    # Subclasses can override this method to provide custom semantic actions
    method evaluate($context) {
        return [map { $_->extract } $context->children->@*];
    }
}

class Chalk::Grammar {
    field $rules        :param :reader;
    field $start_symbol :param :reader;
    field %nullable_cache;
    field %rules_waiting_for;  # Pre-computed: which rules can wait for which symbols

    ADJUST {
        for my $s ( keys(%$rules) ) {
            $self->is_nullable($s);
        }

        # Pre-compute which rules can wait for which symbols
        # For each rule A -> α B β, rule A can wait for symbol B
        for my $lhs (keys %$rules) {
            for my $rule (@{$rules->{$lhs}}) {
                my @rhs = $rule->rhs->@*;
                for my $i (0 .. $#rhs) {
                    my $symbol = $rhs[$i];
                    # This rule can have its dot before $symbol
                    push @{$rules_waiting_for{$symbol} //= []}, {
                        rule => $rule,
                        dot_pos => $i,
                    };
                }
            }
        }
    }

    my sub new_rule( $lhs, $rhs, $probability = 1.0 ) {
        $probability ||= 0.1;
        return Chalk::GrammarRule->new(
            lhs         => $lhs,
            rhs         => $rhs,
            probability => $probability
        );
    }

    my sub insert ( $items, @list ) {
        return [ ( map { $_, @$items } @list[ 0 .. $#list - 1 ] ), $list[-1] ];
    }

    sub build_grammar( $class, %args ) {
        my $auto_insert = $args{auto_insert} // [];
        my $rules_array = $args{rules} // [];

        my %rules = ();
        for my $r (@$rules_array) {
            my ( $lhs, $rhs ) = @$r;
            if ( @$auto_insert && @$rhs > 1 ) {
                $r->[1] = insert( $auto_insert, @$rhs );
            }
            push( @{ $rules{$lhs} //= [] }, new_rule(@$r) );
        }
        return Chalk::Grammar->new( rules => \%rules, start_symbol => $rules_array->[0]->[0] );
    }

    method start_rule() { return $rules->{$start_symbol}->[0] }

    method rules_for($symbol) {
        return $rules->{$symbol}->@* if exists( $rules->{$symbol} );
        return;
    }

    method is_nonterminal($symbol) {
        return exists( $rules->{$symbol} );
    }

    method is_nullable($symbol) {

        # Check cache first
        return $nullable_cache{$symbol} if exists( $nullable_cache{$symbol} );

       # Compute nullability by checking if any rule for this symbol is nullable
        my $result = 0;
        for my $rule ( $self->rules_for($symbol) ) {
            if ( $rule->is_nullable($self) ) {
                $result = 1;
                last;
            }
        }

        # Cache the result
        $nullable_cache{$symbol} = $result;
        return $result;
    }

    method rules_waiting_for($symbol) {
        # Returns list of { rule, dot_pos } that can wait for this symbol
        return $rules_waiting_for{$symbol}->@* if exists($rules_waiting_for{$symbol});
        return;
    }

    method to_string(@) {
        my $grammar = '';
        $grammar .= "Grammar:\n";
        for my $nt ( sort( keys( $rules->%* ) ) ) {
            for my $rule ( $rules->{$nt}->@* ) {
                $grammar .= "  $rule\n";
            }
        }
        $grammar .= "\n";
        return $grammar;
    }
}

1;

package Chalk::Grammar::BNF;
# ABOUTME: Hand-coded BNF grammar for parsing BNF files without regex dependency
# ABOUTME: Defines BNF syntax in Perl for bootstrapping the BNF parser

use 5.42.0;
use experimental 'class';
use Chalk::Grammar;
use Chalk::Grammar::BNF::Rule::Grammar;
use Chalk::Grammar::BNF::Rule::LineList;
use Chalk::Grammar::BNF::Rule::Line;
use Chalk::Grammar::BNF::Rule::GrammarRule;
use Chalk::Grammar::BNF::Rule::RHS;
use Chalk::Grammar::BNF::Rule::RHSElement;
use Chalk::Grammar::BNF::Rule::Terminal;
use Chalk::Grammar::BNF::Rule::BarewordTerminal;
use Chalk::Grammar::BNF::Rule::Nonterminal;
use Chalk::Grammar::BNF::Rule::PatternDef;
use Chalk::Grammar::BNF::Rule::PatternRef;
use Chalk::Grammar::BNF::Rule::Comment;
use Chalk::Grammar::BNF::Rule::BlankLine;

# Export singleton grammar instance
our $grammar;

sub grammar {
    # Works as both sub and method
    shift if @_ && (!ref($_[0]) && $_[0] eq __PACKAGE__);
    return $grammar;
}

# Helper to create rules with custom classes
sub _new_bnf_rule {
    my ($lhs, $rhs, $probability) = @_;
    $probability ||= 1.0;

    # Map LHS nonterminal to appropriate rule class
    my $rule_class = "Chalk::Grammar::BNF::Rule::$lhs";
    my $rule_file = $rule_class;
    $rule_file =~ s|::|/|g;
    $rule_file .= ".pm";

    # Check if the specialized class exists
    if (eval { require $rule_file; 1 }) {
        return $rule_class->new(
            lhs => $lhs,
            rhs => $rhs,
            probability => $probability
        );
    }

    # Fall back to default GrammarRule
    return Chalk::GrammarRule->new(
        lhs => $lhs,
        rhs => $rhs,
        probability => $probability
    );
}

# Build the BNF grammar with semantic action support
sub _build_bnf_grammar {
    my @rules_array = @_;
    my %rules = ();

    for my $r (@rules_array) {
        my ($lhs, $rhs, $prob) = @$r;
        push(@{$rules{$lhs} //= []}, _new_bnf_rule($lhs, $rhs, $prob));
    }

    return Chalk::Grammar->new(
        rules => \%rules,
        start_symbol => $rules_array[0]->[0]
    );
}

# Hand-coded BNF grammar rules
# This grammar is used to parse BNF files like grammar/perl.bnf
$grammar = _build_bnf_grammar(
        # Top level: a BNF file is a list of lines
        ['Grammar', ['LineList']],

        # Lines can be empty, a single line, or contain more lines
        ['LineList', []],  # Empty (base case)
        ['LineList', ['Line']],  # Single line
        ['LineList', ['Line', 'LineList']],  # Multiple lines

        # A line can be a pattern definition, grammar rule, comment, or blank
        # Note: lines in BNF files end with newlines (handled by Line rules)
        ['Line', ['PatternDef', "\n"]],
        ['Line', ['GrammarRule', "\n"]],
        ['Line', ['Comment', "\n"]],
        ['Line', ['BlankLine']],

        # Pattern definitions: %NAME% = /regex/flags or //regex//flags
        # Example: %PATTERN_1% = /unless|if|while/u
        # Example: %PATTERN_21% = //(?:[^/\\]|\\.)*+//u
        # Example: %PATTERN_38% = /\|\||///u  (captures rest of line, semantic action parses)
        ['PatternDef', [
            '%',
            qr/[a-zA-Z_][a-zA-Z0-9_]*/,  # Pattern name
            '%',
            qr/\s*/,                      # Optional whitespace
            '=',
            qr/\s*/,                      # Optional whitespace
            '/',
            qr/[^\n]+/,                   # Rest of line (semantic action will parse)
        ]],

        # Pattern definition with double-slash delimiter
        # Inside //, single / is allowed, but // is the terminator
        ['PatternDef', [
            '%',
            qr/[a-zA-Z_][a-zA-Z0-9_]*/,  # Pattern name
            '%',
            qr/\s*/,                      # Optional whitespace
            '=',
            qr/\s*/,                      # Optional whitespace
            '//',
            qr/(?:[^\/\\]++|\\.|\/(?!\/))*+/,  # Regex content (/ allowed, but not //)
            '//',
            qr/[a-z]*/                    # Optional flags
        ]],

        # Grammar rules: LHS -> RHS (with optional inline comment)
        # Example: Block -> '{' WS_OPT StatementList WS_OPT '}'
        # Example with comment: Foo -> 'bar'  # inline comment
        ['GrammarRule', [
            qr/[A-Z][a-zA-Z0-9_]*/,  # LHS (nonterminal, starts with capital)
            qr/\s*/,                  # Optional whitespace
            '->',
            qr/\s*/,                  # Optional whitespace
            'RHS',
            qr/\s*#[^\n]*/,           # Inline comment (with leading whitespace)
        ]],
        ['GrammarRule', [
            qr/[A-Z][a-zA-Z0-9_]*/,  # LHS (nonterminal, starts with capital)
            qr/\s*/,                  # Optional whitespace
            '->',
            qr/\s*/,                  # Optional whitespace
            'RHS'
        ]],

        # Right-hand side: sequence of RHS elements or empty
        ['RHS', []],  # Empty RHS (epsilon production)
        ['RHS', ['RHSElement']],
        ['RHS', ['RHSElement', qr/\s+/, 'RHS']],

        # RHS elements can be terminals, nonterminals, pattern references, or barewords
        ['RHSElement', ['Terminal']],
        ['RHSElement', ['Nonterminal']],
        ['RHSElement', ['PatternRef']],

#!/usr/bin/env perl
# ABOUTME: Complete chalk grammar test with all modern Perl constructs
# ABOUTME: Build up the grammar systematically to handle self-hosting
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all defer);
use utf8;
use open qw/:std :utf8/;
use Test2::V0;
use FindBin      qw($RealBin);
defer { done_testing() }

use lib "$RealBin/../../lib";
use Chalk::Grammar;
use Chalk::Parser;

# Build a comprehensive grammar for chalk's modern Perl syntax
my $chalk_grammar = Chalk::Grammar->build_grammar(
    rules => [
        # Top-level program structure
        [ 'Program' => ['TopLevelDecls'] ],
        [ 'TopLevelDecls' => ['TopLevelDecl'] ],
        [ 'TopLevelDecls' => [qw(TopLevelDecl TopLevelDecls)] ],

        # Top-level declarations
        [ 'TopLevelDecl' => ['PragmaDecl'] ],
        [ 'TopLevelDecl' => ['ClassDecl'] ],

        # Pragma declarations (use statements)
        [ 'PragmaDecl' => [qw(use Version ;)] ],
        [ 'PragmaDecl' => [qw(use experimental List ;)] ],
        [ 'PragmaDecl' => [qw(use ModuleName ;)] ],

        # Class declarations
        [ 'ClassDecl' => [qw(class Identifier InheritanceClause { ClassBody })] ],
        [ 'ClassDecl' => [qw(class Identifier { ClassBody })] ],
        [ 'InheritanceClause' => [qw(:isa( Identifier ))] ],

        # Class body
        [ 'ClassBody' => ['ClassMember'] ],
        [ 'ClassBody' => [qw(ClassMember ClassBody)] ],
        [ 'ClassMember' => ['UseOverload'] ],
        [ 'ClassMember' => ['FieldDecl'] ],
        [ 'ClassMember' => ['MethodDecl'] ],

        # Use overload declarations
        [ 'UseOverload' => [qw(use overload OverloadList ;)] ],
        [ 'OverloadList' => ['OverloadSpec'] ],
        [ 'OverloadList' => ['OverloadSpec', ',', 'OverloadList'] ],
        [ 'OverloadSpec' => [qw(QuotedString => QuotedString)] ],
        [ 'OverloadSpec' => [qw(Identifier => Number)] ],

        # Field declarations
        [ 'FieldDecl' => [qw(field Variable AttributeList = Expression ;)] ],
        [ 'FieldDecl' => [qw(field Variable AttributeList ;)] ],
        [ 'FieldDecl' => [qw(field Variable = Expression ;)] ],
        [ 'FieldDecl' => [qw(field Variable ;)] ],
        [ 'AttributeList' => ['Attribute'] ],
        [ 'AttributeList' => [qw(Attribute AttributeList)] ],
        [ 'Attribute' => [':param'] ],
        [ 'Attribute' => [':reader'] ],

        # Method declarations
        [ 'MethodDecl' => [qw(method Identifier ( ParamList ) Block)] ],
        [ 'MethodDecl' => [qw(method Identifier ( ) Block)] ],
        [ 'MethodDecl' => [qw(method Identifier (@) Block)] ],
        [ 'ParamList' => ['Param'] ],
        [ 'ParamList' => ['Param', ',', 'ParamList'] ],
        [ 'Param' => [qw(Variable = Default)] ],
        [ 'Param' => ['Variable'] ],
        [ 'Default' => ['undef'] ],
        [ 'Default' => ['Number'] ],

        # Blocks and statements
        [ 'Block' => [qw({ StatementList })] ],
        [ 'Block' => [qw({ })] ],
        [ 'StatementList' => ['Statement'] ],
        [ 'StatementList' => [qw(Statement StatementList)] ],
        [ 'Statement' => [qw(return Expression ;)] ],
        [ 'Statement' => [qw(my Variable = Expression ;)] ],
        [ 'Statement' => [qw(state Variable = Expression ;)] ],
        [ 'Statement' => [qw(for my Variable ( Expression ) Block)] ],
        [ 'Statement' => [qw(if ( Expression ) Block)] ],
        [ 'Statement' => [qw(Expression ;)] ],
        [ 'Statement' => [qw({ StatementList })] ],  # Nested block
        [ 'Statement' => ['Ellipsis'] ],

        # Expressions
        [ 'Expression' => ['MethodCall'] ],
        [ 'Expression' => ['Constructor'] ],
        [ 'Expression' => ['HashAccess'] ],
        [ 'Expression' => ['StringConcat'] ],
        [ 'Expression' => ['PostfixDeref'] ],
        [ 'Expression' => ['BuiltinCall'] ],
        [ 'Expression' => ['Variable'] ],
        [ 'Expression' => ['Literal'] ],
        [ 'Expression' => [qw(( Expression ))] ],

        # Method calls and constructors
        [ 'MethodCall' => [qw(Expression -> Identifier ( ArgList ))] ],
        [ 'MethodCall' => [qw(Expression -> Identifier ( ))] ],
        [ 'Constructor' => [qw(Identifier -> new ( ArgList ))] ],
        [ 'Constructor' => [qw(Identifier -> new ( ))] ],

        # Hash access and assignment
        [ 'HashAccess' => [qw(Variable { Expression })] ],
        [ 'HashAccess' => [qw(Variable { Expression } //= Expression)] ],

        # String concatenation
        [ 'StringConcat' => [qw(Expression . Expression)] ],

        # Postfix dereference
        [ 'PostfixDeref' => [qw(Expression -> ArrayDeref)] ],
        [ 'PostfixDeref' => [qw(Expression -> HashDeref)] ],
        [ 'ArrayDeref' => ['@*'] ],
        [ 'HashDeref' => ['%*'] ],

        # Builtin function calls
        [ 'BuiltinCall' => [qw(all { Block } Expression)] ],
        [ 'BuiltinCall' => [qw(any { Block } Expression)] ],

        # Argument lists
        [ 'ArgList' => ['Argument'] ],
        [ 'ArgList' => ['Argument', ',', 'ArgList'] ],
        [ 'Argument' => [qw(Identifier => Expression)] ],
        [ 'Argument' => ['Expression'] ],

        # Variables
        [ 'Variable' => ['ScalarVar'] ],
        [ 'Variable' => ['ArrayVar'] ],
        [ 'Variable' => ['HashVar'] ],
        [ 'ScalarVar' => ['$var'] ],
        [ 'ArrayVar' => ['@var'] ],
        [ 'HashVar' => ['%var'] ],

        # Literals and identifiers
        [ 'Literal' => ['Number'] ],
        [ 'Literal' => ['QuotedString'] ],
        [ 'Literal' => ['ArrayRef'] ],
        [ 'Literal' => ['HashRef'] ],
        [ 'ArrayRef' => [qw([ ])] ],
        [ 'ArrayRef' => [qw([ ExprList ])] ],
        [ 'HashRef' => [qw({ })] ],
        [ 'HashRef' => [qw({ HashPairs })] ],
        [ 'ExprList' => ['Expression'] ],
        [ 'ExprList' => ['Expression', ',', 'ExprList'] ],
        [ 'HashPairs' => ['HashPair'] ],
        [ 'HashPairs' => ['HashPair', ',', 'HashPairs'] ],
        [ 'HashPair' => [qw(Expression => Expression)] ],

