        [ 'Identifier' => ['Element'] ],
        [ 'Identifier' => ['ViterbiElement'] ],
        [ 'Identifier' => ['SPPFForest'] ],
        [ 'Identifier' => ['new'] ],
        [ 'Identifier' => ['method'] ],
        [ 'ModuleName' => ['overload'] ],
        [ 'ModuleName' => ['experimental'] ],
        [ 'Number' => ['0'] ],
        [ 'Number' => ['1'] ],
        [ 'Number' => ['-1e10'] ],
        [ 'QuotedString' => ["'+'"] ],
        [ 'QuotedString' => ["'add'"] ],
        [ 'QuotedString' => ["'ε'"] ],
        [ 'QuotedString' => ['"string"'] ],
