    17→        my @lines = split /\n/, $input, -1;
    18→        my @output_lines;
    19→        my %line_mapping;
    20→        my $output_line_num = 0;
    21→
    22→        for (my $i = 0; $i < @lines; $i++) {
    23→            my $input_line_num = $i + 1;
    24→            my $line = $lines[$i];
    25→
    26→            # Find heredoc markers in this line using the grammar
    27→            my @heredocs = $self->find_heredocs_in_line($line);
    28→
    29→            if (@heredocs) {
    30→                # Collect content for each heredoc
    31→                my $j = $i + 1;
    32→                my @transformed_parts;
    33→                my $all_found = 1;
    34→
