    19→        if (defined($value) && $value =~ /^[0-9]+$/ && $value == 0) {
    20→            return $other;
    21→        }
    22→
    23→        # Prefer elements with evaluated focus (defined) over unevaluated (undef)
    24→        # This handles the case where we update the chart after evaluation
    25→        my $self_focus = $self->context->focus;
    26→        my $other_focus = $other->context->focus;
    27→
    28→        if (!defined($self_focus) && defined($other_focus)) {
    29→            return $other;
    30→        }
