     2→# ABOUTME: Uses mini-grammar to correctly parse heredoc markers in code context
     3→package Chalk::Preprocessor::Heredoc;
     4→use 5.42.0;
     5→use utf8;
     6→use open qw(:std :utf8);
     7→
     8→use experimental qw(class builtin keyword_any keyword_all);
     9→#use Chalk::Parser;
    10→
    11→class Chalk::Preprocessor::Heredoc {
    12→    field $input :param :reader;
    13→    field $output :reader = '';
    14→    field @line_map :reader;
    15→
    16→    method transform() {
    17→        my @lines = split /\n/, $input, -1;
    18→        my @output_lines;
    19→        my %line_mapping;
    20→        my $output_line_num = 0;
    21→
    22→        for (my $i = 0; $i < @lines; $i++) {
    23→            my $input_line_num = $i + 1;
    24→            my $line = $lines[$i];
    25→
    26→            # Find heredoc markers in this line using the grammar
    27→            my @heredocs = $self->find_heredocs_in_line($line);
    28→
    29→            if (@heredocs) {
    30→                # Collect content for each heredoc
    31→                my $j = $i + 1;
    32→                my @transformed_parts;
    33→                my $all_found = 1;
    34→
    35→                for my $hd (@heredocs) {
    36→                    my @heredoc_content;
    37→                    my $found_terminator = 0;
    38→
    39→                    while ($j < @lines) {
    40→                        my $line_matches = 0;
    41→                        if ($hd->{is_indented}) {
    42→                            $line_matches = ($lines[$j] =~ /^\s*\Q$hd->{delimiter}\E$/);
    43→                        } else {
    44→                            $line_matches = ($lines[$j] eq $hd->{delimiter});
    45→                        }
    46→
    47→                        if ($line_matches) {
    48→                            $found_terminator = 1;
    49→                            $j++;
    50→                            last;
    51→                        }
    52→                        push @heredoc_content, $lines[$j];
    53→                        $j++;
    54→                    }
    55→
    56→                    if ($found_terminator) {
    57→                        if ($hd->{is_indented}) {
    58→                            @heredoc_content = $self->strip_indentation(@heredoc_content);
    59→                        }
    60→
    61→                        my $content = join("\n", @heredoc_content);
    62→
    63→                        # Recursively transform nested heredocs ONLY in double-quoted heredocs
    64→                        # Single-quoted heredocs don't interpolate, so <<FOO inside them is literal
    65→                        if (!$hd->{is_single_quoted}) {
    66→                            my $inner_preprocessor = Chalk::Preprocessor::Heredoc->new(input => $content);
    67→                            $inner_preprocessor->transform();
    68→                            $content = $inner_preprocessor->output;
    69→                        }
    70→
    71→                        my $quote_op = $hd->{is_single_quoted} ? 'q' : 'qq';
    72→                        my ($open, $close) = $self->choose_delimiters($content);
    73→                        push @transformed_parts, {
    74→                            marker => $hd->{marker},
    75→                            replacement => "${quote_op}${open}${content}${close}",
    76→                        };
    77→                    } else {
    78→                        $all_found = 0;
    79→                        last;
    80→                    }
    81→                }
    82→
    83→                if ($all_found && @transformed_parts) {
    84→                    # Replace markers with transformations
    85→                    my $transformed = $line;
    86→                    for my $part (@transformed_parts) {
    87→                        $transformed =~ s/\Q$part->{marker}\E/$part->{replacement}/;
    88→                    }
    89→
    90→                    push @output_lines, $transformed;
    91→                    $line_mapping{$output_line_num} = $input_line_num;
    92→                    $output_line_num++;
    93→                    $i = $j - 1;  # Skip content lines
    94→                } else {
    95→                    # Couldn't find terminators, keep original
    96→                    push @output_lines, $line;
    97→                    $line_mapping{$output_line_num} = $input_line_num;
    98→                    $output_line_num++;
    99→                }
   100→            } else {
   101→                # No heredocs, keep as-is
   102→                push @output_lines, $line;
   103→                $line_mapping{$output_line_num} = $input_line_num;
   104→                $output_line_num++;
   105→            }
   106→        }
