   110→    }
   111→
   112→    method find_heredocs_in_line($line) {
   113→        # Scan for heredoc markers, but skip those inside strings or comments
   114→        # Strategy: Find all heredocs first, then filter out those in strings/comments
   115→
   116→        my @heredocs;
