   122→        # Find single-quoted string ranges (but not heredoc markers like <<'EOF')
   123→        while ($working_line =~ /(?<!<)'(?:[^'\\]|\\.)*'/g) {
   124→            my $end = pos($working_line);
   125→            my $start = $end - length($&);
   126→            push @excluded_ranges, [$start, $end];
   127→        }
   128→
   129→        # Find double-quoted string ranges
   130→        while ($working_line =~ /"(?:[^"\\]|\\.)*"/g) {
   131→            my $end = pos($working_line);
   132→            my $start = $end - length($&);
